import{_ as n,a0 as a,w as s,s as d,ao as p,I as i,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse(`{"title":"Torvalds: 寫linux內核的人更加容易找工作 | LCTT x X-CMD","titleTemplate":false,"description":"Torvalds: 寫linux內核的人更加容易找工作 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Torvalds: 寫linux內核的人更加容易找工作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Torvalds: 寫linux內核的人更加容易找工作 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'","title":"Torvalds: 寫linux內核的人更加容易找工作","tag":"201504","desc":""},"relativePath":"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'.md","filePath":"[post].md"}`),u={name:"201504/20150225 Torvalds--'People who start writing kernel code get hired really quickly'.md"};function m(T,t,x,g,w,f){const l=a("Link");return s(),d("div",null,[t[13]||(t[13]=p('<h1 id="torvalds-寫linux內核的人更加容易找工作" tabindex="-1">Torvalds: 寫linux內核的人更加容易找工作 <a class="header-anchor" href="#torvalds-寫linux內核的人更加容易找工作" aria-label="Permalink to “Torvalds: 寫linux內核的人更加容易找工作”">​</a></h1><p>相比起以往，linux內核開發這麼專業的事情，在最近發佈的《誰在編寫 Linux》報告中，其無償貢獻者降到了歷史最低水平。</p><p>這個報道由linux基金會撰寫，上年有11.8%的內核開發是由無償貢獻者完成，相比2012年的14.6%下滑了19%。基金會説貢獻者有逐年下降的趨勢。</p><p><img src="http://images.techhive.com/images/article/2015/02/screen-shot-2015-02-17-at-5.25.43-pm-100568680-medium.idge.png" alt=""></p><p>即使是這樣，在最新的《誰在編寫 Linux》報告裏，無償貢獻者還是最大的單一貢獻來源，共做了11968 處修改，佔整體的12.4%。然而，linux基金會説，企業貢獻者共同佔比越來越多，超過80%的內核貢獻是由有償的專業開發者完成的。</p><p>根據 linus Torvalds 説，這個有償開發者趨勢不會對內核開發的本身有太多改變。</p><p>他向《Network World》説，“我認為不會改變太多的一個原因是，其實並不是‘無償貢獻者離開了’，而是‘編寫內核的人很快就被僱走了’。”</p><p>Torvalds講到，linux開發的改變有很多其他原因，很自然的，新的貢獻者會經常冒出來；有很多原來的開發者，有的有着10年的經驗，被很多對linux感興趣的公司搶去了。</p><p>他説：“開始我們是自願者，但我們後來也很高興被請去開發linux。”</p><p>Torvalds 開始抽離了他的開發角色，根據報道在3.10的內核版本里面他個人發佈了329個補丁，佔04%。逐漸地，各個子系統的維護人員自己開始做代碼檢查與合併。</p><hr>',11)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),r(l,{href:"http://www.infoworld.com/article/2885339/application-development/torvalds-people-who-start-writing-kernel-code-get-hired-really-quickly.html"},{default:o(()=>[...t[0]||(t[0]=[e("http://www.infoworld.com/article/2885339/application-development/torvalds-people-who-start-writing-kernel-code-get-hired-really-quickly.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),r(l,{href:"http://www.infoworld.com/author/Jon-Gold/"},{default:o(()=>[...t[2]||(t[2]=[e("Jon Gold",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),r(l,{href:"https://github.com/haimingfg"},{default:o(()=>[...t[3]||(t[3]=[e("haimingfg",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),r(l,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const _=n(u,[["render",m]]);export{k as __pageData,_ as default};
